head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil15302";
scwin.sizeX = 440;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil15302.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.initValue();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15302.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_GetLawItemContents_xhr
 * @description Get Law Item Contents xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_GetLawItemContents_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_GetLawItemContents_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_GetLawItemContents_xhr", unresolved: "action:self_submit:tx_fn_GetLawItemContents_xhr" };
};

/**
 * @method
 * @name tx_fn_GetLawDtruleItemContents_xhr
 * @description Get Law Dtrule Item Contents xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_GetLawDtruleItemContents_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_GetLawDtruleItemContents_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_GetLawDtruleItemContents_xhr", unresolved: "action:self_submit:tx_fn_GetLawDtruleItemContents_xhr" };
};

/**
 * @method
 * @name winResize
 * @description win Resize 처리
 * @returns {void}
 * @hidden N
 */
scwin.winResize = function () {
    scwin.resizeX();
    scwin.resizeY();
};

/**
 * @method
 * @name resizeX
 * @description resize X 처리
 * @returns {void}
 * @hidden N
 */
scwin.resizeX = function () {

};

/**
 * @method
 * @name resizeY
 * @description resize Y 처리
 * @returns {void}
 * @hidden N
 */
scwin.resizeY = function () {
    const sh = document.body.scrollHeight;
    let sizeY = 500;
    if (sh < 500) {
        sizeY = sh + 30;
    }

};

/**
 * @method
 * @name initValue
 * @description init Value 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initValue = async function () {
    await scwin.getLawItemContents();
    await scwin.getLawDtruleItemContents();

};

/**
 * @method
 * @name getLawItemContents
 * @description get Law Item Contents 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getLawItemContents = async function () {
    const frm = (document.lawItemForm || { elements: [] });
    $c.util.getComponent('dma_GetLawItemContentsXhrReq').set('method', "viewLawItem");
    frm.action = "popLaw.do";
    const result = await scwin.tx_fn_GetLawItemContents_xhr();
    const divObj = $c.util.getComponent("law1");
    divObj.innerHTML = result;
    scwin.sizeX = 440;
    scwin.winResize();
};

/**
 * @method
 * @name getLawDtruleItemContents
 * @description get Law Dtrule Item Contents 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getLawDtruleItemContents = async function () {
    const frm = (document.lawItemForm || { elements: [] });
    $c.util.getComponent('dma_GetLawItemContentsXhrReq').set('method', "viewLawDtruleItem");
    frm.action = "popLaw.do";
    let result = await scwin.tx_fn_GetLawDtruleItemContents_xhr();
    result = $c.str.trim(result);
    if (result !== '') {
        const divObj = $c.util.getComponent("txt_law2");
        divObj.innerHTML = result;
        scwin.sizeX = 900;
    } else {
        scwin.sizeX = 455;
    }
    scwin.winResize();
    scwin.setTableHeight();
};

/**
 * @method
 * @name setTableHeight
 * @description set Table Height 처리
 * @returns {void}
 * @hidden N
 */
scwin.setTableHeight = function () {
    const tab1 = $c.util.getComponent("tab1");
    const tab2 = $c.util.getComponent("tab2");
    const height1 = tab1.offsetHeight;
    const height2 = tab2.offsetHeight;
    const maxHeight = (height1 > height2) ? height1 : height2;
    tab1.setStyle('height', maxHeight);
    tab2.setStyle('height', maxHeight);
};
